 collection text, "sourceCode" text, "sourceName" text, "sourceSHA" text,
 "canStand" boolean, points jsonb, width int, height int, "mountDepth" numeric, "placementOffset" jsonb
)) UPDATE dndshare.map_model m SET geometry=m.geometry || jsonb_build_object('canStand',r."canStand",'placementPoints',r.points)
FROM measured r WHERE m.collection=r.collection AND m.source_code=r."sourceCode" AND m.source_name=r."sourceName"
AND m.assets->'source'->>'sha256'=r."sourceSHA" AND (m.geometry->>'width')::int=r.width AND (m.geometry->>'height')::int=r.height
AND abs((m.geometry->>'mountDepth')::numeric-r."mountDepth")<.00001
AND coalesce(m.geometry->'placementOffset','[0,0]'::jsonb)=r."placementOffset"
AND NOT (m.geometry->>'hidden')::boolean;
